questions.solution:
function total(label, ...amounts) {
  const sum = amounts.reduce((acc, n) => acc + n, 0);
  return `${label}: ${sum}`;
}

console.log(total("Groceries", 4, 5, 3));
const week = [10, 20, 5];
console.log(total("Week", ...week));
console.log(total("Nothing"));

